import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

async function authorized(amount = 2) {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', amount), { ok: true });
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  return h;
}

test('authorize sends one request', async () => {
  const h = await createHost();
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  const effects = await h.pendingEffects();
  assert.equal(effects.length, 1);
  assert.equal(effects[0].from, 'p');
  assert.equal(effects[0].kind, 'card.authorize');
  assert.deepEqual(effects[0].data, { amount: 2 });
  assert.deepEqual(await h.payment('p'), { status: 'authorizing', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal(await h.payment('q'), null);
});

test('authorize refusals', async () => {
  const h = await createHost();
  for (const a of [0, 3, 1.5, -1]) assert.equal((await h.authorize('p', a)).ok, false);
  assert.equal(await h.payment('p'), null);
  await h.authorize('p', 1);
  assert.equal((await h.authorize('p', 2)).ok, false);
  assert.equal((await h.pendingEffects()).length, 1);
});

test('unknown payments are refused', async () => {
  const h = await createHost();
  for (const r of [await h.timedOut('x'), await h.capture('x', 1), await h.void('x'), await h.refund('x', 1)])
    assert.equal(r.ok, false);
});

test('timeouts retry up to 3 then fail; late answers ignored', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('first answer decides', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(b.id, 'failed');
  assert.equal((await h.payment('p'))!.status, 'declined');
  await h.completeEffect(a.id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'declined');
  assert.equal((await h.timedOut('p')).ok, false);
  assert.equal((await h.capture('p', 1)).ok, false);
});

test('capture, refund', async () => {
  const h = await authorized(2);
  assert.equal((await h.refund('p', 1)).ok, false);
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'captured');
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  assert.equal((await h.refund('p', 1)).ok, false);
});

test('cannot capture beyond authorised', async () => {
  const h = await authorized(1);
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.deepEqual(await h.capture('p', 1), { ok: true });
});

test('void', async () => {
  const h = await authorized(1);
  assert.deepEqual(await h.void('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'voided', authorized: 1, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
});

