      capture: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: amountDomain },
      void: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      refund: { action: (data = {}) => ({ ...data }), schema: { amount: 'number' }, domain: amountDomain },
