// Drives src/host.impl.ts through scenarios and writes one NDJSON trace per
// scenario to spec/traces/, via the system's tracer seam.
// Run: node spec/capture.ts
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { createSystem, type Step } from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const toState = (s: Step['pre']) => ({
  status: s.payment ? s.payment.status : 'none',
  authorized: s.payment ? s.payment.authorized : 0,
  captured: s.payment ? s.payment.captured : 0,
  refunded: s.payment ? s.payment.refunded : 0,
  requests: s.payment ? s.payment.requests : 0,
  pending: s.pending,
});

type Scenario = (h: Host, answer: (n: number, o: 'ok' | 'failed') => Promise<void>) => Promise<void>;

const scenarios: Record<string, Scenario> = {
  'refund-in-full': async (h, answer) => {
    await h.capture('p', 1);
    await h.authorize('p', 3);
    await h.authorize('p', 2);
    await h.authorize('p', 1);
    await h.capture('p', 1);
    await answer(0, 'ok');
    await h.timedOut('p');
    await h.capture('p', 3);
    await h.capture('p', 2);
    await h.capture('p', 1);
    await h.refund('p', 0);
    await h.refund('p', 1);
    await h.refund('p', 2);
    await h.refund('p', 1);
    await h.refund('p', 1);
    await h.void('p');
  },
  'partial-capture': async (h, answer) => {
    await h.authorize('p', 2);
    await h.timedOut('p');
    await answer(1, 'ok');
    await answer(0, 'failed');
    await h.capture('p', 1);
    await h.refund('p', 2);
    await h.refund('p', 1);
  },
  'small-capture': async (h, answer) => {
    await h.authorize('p', 1);
    await answer(0, 'ok');
    await h.capture('p', 2);
    await h.capture('p', 1);
    await h.refund('p', 1);
  },
  'void': async (h, answer) => {
    await h.void('p');
    await h.authorize('p', 1);
    await h.void('p');
    await answer(0, 'ok');
    await h.void('p');
    await h.void('p');
    await h.capture('p', 1);
    await h.refund('p', 1);
    await h.timedOut('p');
  },
  'declined': async (h, answer) => {
    await h.authorize('p', 2);
    await answer(0, 'failed');
    await h.timedOut('p');
    await h.capture('p', 1);
  },
  'declined-then-late-approval': async (h, answer) => {
    await h.authorize('p', 1);
    await h.timedOut('p');
    await h.timedOut('p');
    await answer(2, 'failed');
    await answer(0, 'ok');
    await answer(0, 'ok');
    await h.void('p');
  },
  'failed-after-3-requests': async (h, answer) => {
    await h.authorize('p', 2);
    await h.timedOut('p');
    await h.timedOut('p');
    await h.timedOut('p');
    await h.timedOut('p');
    await answer(0, 'ok');
    await answer(0, 'failed');
    await h.capture('p', 2);
    await answer(0, 'ok');
  },
};

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, run] of Object.entries(scenarios)) {
  const lines: string[] = [];
  const h = createSystem((step) => {
    if (step.payment !== 'p') return;
    lines.push(JSON.stringify({ pre: toState(step.pre), action: step.action, data: step.data, post: toState(step.post) }));
  });
  const answer = async (n: number, outcome: 'ok' | 'failed') => {
    const effects = (await h.pendingEffects()).filter((e) => e.from === 'p');
    if (effects[n]) await h.completeEffect(effects[n].id, outcome);
  };
  await run(h, answer);
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log(`captured ${Object.keys(scenarios).length} scenarios`);

