// Drives src/host.impl.ts through scenarios and writes one NDJSON trace per
// scenario to spec/traces/, via the system's tracer seam.
// Run: node spec/capture.ts
import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { createSystem, type Step } from '../src/host.impl.ts';
import type { Host } from '../host.ts';

const toState = (s: Step['pre']) => ({
  status: s.payment ? s.payment.status : 'none',
  authorized: s.payment ? s.payment.authorized : 0,
  captured: s.payment ? s.payment.captured : 0,
  refunded: s.payment ? s.payment.refunded : 0,
  requests: s.payment ? s.payment.requests : 0,
  pending: s.pending,
});

type Scenario = (h: Host, answer: (n: number, o: 'ok' | 'failed') => Promise<void>) => Promise<void>;

const scenarios: Record<string, Scenario> = {
  'refund-in-full': async (h, answer) => {
    await h.capture('p', 1);
    await h.authorize('p', 3);
    await h.authorize('p', 2);
    await h.authorize('p', 1);
    await h.capture('p', 1);
    await answer(0, 'ok');
    await h.timedOut('p');
    await h.capture('p', 3);
    await h.capture('p', 2);
    await h.capture('p', 1);
    await h.refund('p', 0);
    await h.refund('p', 1);
    await h.refund('p', 2);
    await h.refund('p', 1);
    await h.refund('p', 1);
    await h.void('p');
  },
  'partial-capture': async (h, answer) => {
    await h.authorize('p', 2);
    await h.timedOut('p');
    await answer(1, 'ok');
    await answer(0, 'failed');
    await h.capture('p', 1);
    await h.refund('p', 2);
    await h.refund('p', 1);
  },
  'small-capture': async (h, answer) => {
    await h.authorize('p', 1);
    await answer(0, 'ok');
    await h.capture('p', 2);
    await h.capture('p', 1);
    await h.refund('p', 1);
  },
  'increase-to-3': async (h, answer) => {
    await h.increase('p');
    await h.authorize('p', 1);
    await h.increase('p');
    await answer(0, 'ok');
    await h.capture('p', 2);
    await h.increase('p');
    await h.capture('p', 3);
    await h.increase('p');
    await h.increase('p');
    await h.capture('p', 4);
    await h.capture('p', 3);
    await h.increase('p');
    await h.refund('p', 2);
    await h.refund('p', 2);
    await h.refund('p', 1);
  },
  'increase-then-void': async (h, answer) => {
    await h.authorize('p', 2);
    await answer(0, 'ok');
    await h.increase('p');
    await h.void('p');
    await h.increase('p');
  },
  'void': async (h, answer) => {
    await h.void('p');
    await h.authorize('p', 1);
    await h.void('p');
    await answer(0, 'ok');
    await h.void('p');
    await h.void('p');
    await h.capture('p', 1);
    await h.refund('p', 1);
    await h.timedOut('p');
  },
  'declined': async (h, answer) => {
    await h.authorize('p', 2);
    await answer(0, 'failed');
    await h.timedOut('p');
    await h.capture('p', 1);
  },
  'declined-then-late-approval': async (h, answer) => {
    await h.authorize('p', 1);
    await h.timedOut('p');
    await h.timedOut('p');
    await answer(2, 'failed');
    await answer(0, 'ok');
    await answer(0, 'ok');
    await h.void('p');
  },
  'failed-after-3-requests': async (h, answer) => {
    await h.authorize('p', 2);
    await h.timedOut('p');
    await h.timedOut('p');
    await h.timedOut('p');
    await h.timedOut('p');
    await answer(0, 'ok');
    await answer(0, 'failed');
    await h.capture('p', 2);
    await answer(0, 'ok');
  },
};

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, run] of Object.entries(scenarios)) {
  const lines: string[] = [];
  const h = createSystem((step) => {
    if (step.payment !== 'p') return;
    lines.push(JSON.stringify({ pre: toState(step.pre), action: step.action, data: step.data, post: toState(step.post) }));
  });
  const answer = async (n: number, outcome: 'ok' | 'failed') => {
    const effects = (await h.pendingEffects()).filter((e) => e.from === 'p');
    if (effects[n]) await h.completeEffect(effects[n].id, outcome);
  };
  await run(h, answer);
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log(`captured ${Object.keys(scenarios).length} scenarios`);

prompt:
The brief has changed. Here is the change, in addition to everything the brief said before:

# Change 3: capture in parts

A payment can now be captured in several parts, for example when an order ships in two parcels.

- `capture(payment, amount)`: on an authorized payment, as before. On a captured payment that has not been refunded at all, it captures `amount` more, as long as the total captured stays at most the amount authorised; the payment stays captured. Refused otherwise.
- Once any amount has been refunded, no further capture is taken.

Everything else is as before.

The host interface is now as follows, and `host.ts` has been updated to match.

```ts
// T3 after change 2, card payments with raised and expiring authorisations: the host interface every arm implements (PT13).

/** The outcome of a command: it took effect, or it was refused and changed nothing. */
export type Outcome = { ok: true } | { ok: false; reason: string };

/** An effect the system asked the outside world to carry out, not yet completed. */
export interface Effect {
  id: string;
  /** The payment that requested it. */
  from: string;
  kind: string;
  data: Record<string, unknown>;
}

/** The effect port: what the card provider is asked to do, and its answers. */
export interface Effects {
  /** Every effect requested and not yet completed, in no promised order. */
  pendingEffects(): Promise<Effect[]>;
  /** The provider's answer to a pending effect: approved (ok) or declined (failed). */
  completeEffect(id: string, outcome: 'ok' | 'failed'): Promise<void>;
}

export interface PaymentView {
  status: 'authorizing' | 'authorized' | 'declined' | 'failed' | 'captured' | 'voided' | 'refunded' | 'expired';
  authorized: number;
  captured: number;
  refunded: number;
  requests: number;
}

export interface Host extends Effects {
  authorize(payment: string, amount: number): Promise<Outcome>;
  timedOut(payment: string): Promise<Outcome>;
  capture(payment: string, amount: number): Promise<Outcome>;
  void(payment: string): Promise<Outcome>;
  increase(payment: string): Promise<Outcome>;
  expire(payment: string): Promise<Outcome>;
  refund(payment: string, amount: number): Promise<Outcome>;
  /** The payment, or null when no payment has that id. */
  payment(payment: string): Promise<PaymentView | null>;
}

/** The module's default export: a factory of a fresh system, with no payments. */
export type CreateHost = () => Promise<Host>;
```

Update your delivery to satisfy the brief as changed, keeping everything the change does not touch. Test your work as you go. When you are done, say so in one line.

