import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

async function authorized(amount = 2) {
  const h = await createHost();
  assert.deepEqual(await h.authorize('p', amount), { ok: true });
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  return h;
}

test('authorize sends one request', async () => {
  const h = await createHost();
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  const effects = await h.pendingEffects();
  assert.equal(effects.length, 1);
  assert.equal(effects[0].from, 'p');
  assert.equal(effects[0].kind, 'card.authorize');
  assert.deepEqual(effects[0].data, { amount: 2 });
  assert.deepEqual(await h.payment('p'), { status: 'authorizing', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal(await h.payment('q'), null);
});

test('authorize refusals', async () => {
  const h = await createHost();
  for (const a of [0, 3, 1.5, -1]) assert.equal((await h.authorize('p', a)).ok, false);
  assert.equal(await h.payment('p'), null);
  await h.authorize('p', 1);
  assert.equal((await h.authorize('p', 2)).ok, false);
  assert.equal((await h.pendingEffects()).length, 1);
});

test('unknown payments are refused', async () => {
  const h = await createHost();
  for (const r of [await h.timedOut('x'), await h.capture('x', 1), await h.void('x'), await h.refund('x', 1)])
    assert.equal(r.ok, false);
});

test('timeouts retry up to 3 then fail; late answers ignored', async () => {
  const h = await createHost();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.pendingEffects()).length, 3);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.payment('p'))!.requests, 3);
  assert.equal((await h.timedOut('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
});

test('first answer decides', async () => {
  const h = await createHost();
  await h.authorize('p', 2);
  await h.timedOut('p');
  const [a, b] = await h.pendingEffects();
  await h.completeEffect(b.id, 'failed');
  assert.equal((await h.payment('p'))!.status, 'declined');
  await h.completeEffect(a.id, 'ok');
  assert.equal((await h.payment('p'))!.status, 'declined');
  assert.equal((await h.timedOut('p')).ok, false);
  assert.equal((await h.capture('p', 1)).ok, false);
});

test('capture, refund', async () => {
  const h = await authorized(2);
  assert.equal((await h.refund('p', 1)).ok, false);
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.payment('p'))!.status, 'captured');
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  assert.equal((await h.refund('p', 1)).ok, false);
});

test('cannot capture beyond authorised', async () => {
  const h = await authorized(1);
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.deepEqual(await h.capture('p', 1), { ok: true });
});

test('increase', async () => {
  const h = await authorized(1);
  assert.equal((await h.capture('p', 2)).ok, false);
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.payment('p'))!.authorized, 3);
  assert.equal((await h.capture('p', 4)).ok, false);
  assert.deepEqual(await h.capture('p', 3), { ok: true });
  assert.equal((await h.increase('p')).ok, false);
  assert.deepEqual(await h.refund('p', 2), { ok: true });
  assert.equal((await h.refund('p', 3)).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 3, captured: 3, refunded: 3, requests: 1 });
});

test('increase refusals', async () => {
  const h = await createHost();
  assert.equal((await h.increase('x')).ok, false);
  await h.authorize('p', 2);
  assert.equal((await h.increase('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  await h.void('p');
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.payment('p'))!.authorized, 2);
});

test('expire', async () => {
  const h = await authorized(2);
  assert.deepEqual(await h.expire('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'expired', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  for (const r of [
    await h.expire('p'), await h.capture('p', 1), await h.void('p'), await h.increase('p'),
    await h.refund('p', 1), await h.timedOut('p'), await h.authorize('p', 1),
  ]) assert.equal(r.ok, false);
  assert.equal((await h.payment('p'))!.status, 'expired');
});

test('expire refusals', async () => {
  const h = await createHost();
  assert.equal((await h.expire('x')).ok, false);
  await h.authorize('p', 2);
  assert.equal((await h.expire('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  await h.capture('p', 1);
  assert.equal((await h.expire('p')).ok, false);
  assert.equal((await h.payment('p'))!.status, 'captured');
});

test('void', async () => {
  const h = await authorized(1);
  assert.deepEqual(await h.void('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'voided', authorized: 1, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('p', 1)).ok, false);
  assert.equal((await h.void('p')).ok, false);
});

// The rules the brief requires, as polygraph invariants over one payment.
const STATUSES = ['none', 'authorizing', 'authorized', 'declined', 'failed', 'captured', 'voided', 'refunded', 'expired'];

export const stateInvariants = [
  { name: 'known-status', pred: (s) => STATUSES.includes(s.status) },
  { name: 'authorized-is-1-to-3', pred: (s) => s.status === 'none' || [1, 2, 3].includes(s.authorized) },
  { name: 'nothing-captured-beyond-authorised', pred: (s) => s.captured <= s.authorized },
  { name: 'nothing-refunded-beyond-captured', pred: (s) => s.refunded <= s.captured },
  { name: 'at-most-3-requests', pred: (s) => s.requests <= 3 },
  { name: 'pending-at-most-requests', pred: (s) => s.pending >= 0 && s.pending <= s.requests },
  { name: 'expired-captured-nothing', pred: (s) => s.status !== 'expired' || (s.captured === 0 && s.refunded === 0) },
  { name: 'voided-captured-nothing', pred: (s) => s.status !== 'voided' || (s.captured === 0 && s.refunded === 0) },
  {
    name: 'money-moves-only-after-capture',
    pred: (s) => ['captured', 'refunded'].includes(s.status) || (s.captured === 0 && s.refunded === 0),
  },
  { name: 'captured-status-has-money', pred: (s) => !['captured', 'refunded'].includes(s.status) || s.captured >= 1 },
  { name: 'refunded-means-all-refunded', pred: (s) => s.status !== 'refunded' || s.refunded === s.captured },
  { name: 'captured-means-not-all-refunded', pred: (s) => s.status !== 'captured' || s.refunded < s.captured },
  { name: 'failed-only-after-3-requests', pred: (s) => s.status !== 'failed' || s.requests === 3 },
];

const changed = (pre, post) => JSON.stringify(pre) !== JSON.stringify(post);

export const transitionInvariants = [
  {
    name: 'authorized-amount-changes-only-by-increase',
    pred: (pre, a, d, post) =>
      pre.status === 'none' ||
      post.authorized === pre.authorized ||
      (a === 'increase' && pre.status === 'authorized' && pre.captured === 0 && post.authorized === pre.authorized + 1),
  },
  {
    name: 'increase-changes-only-authorized',
    pred: (pre, a, d, post) =>
      a !== 'increase' || JSON.stringify({ ...pre, authorized: 0 }) === JSON.stringify({ ...post, authorized: 0 }),
  },
  {
    name: 'invalid-capture-amount-changes-nothing',
    pred: (pre, a, d, post) => a !== 'capture' || [1, 2, 3].includes(d.amount) || !changed(pre, post),
  },
  { name: 'captured-never-decreases', pred: (pre, a, d, post) => post.captured >= pre.captured },
  { name: 'refunded-never-decreases', pred: (pre, a, d, post) => post.refunded >= pre.refunded },
  { name: 'requests-never-decrease', pred: (pre, a, d, post) => post.requests >= pre.requests },
  {
    name: 'answer-decides-only-authorizing',
    pred: (pre, a, d, post) => a !== 'complete' || pre.status === 'authorizing' || post.status === pre.status,
  },
  {
    name: 'invalid-amount-changes-nothing',
    pred: (pre, a, d, post) =>
      (a !== 'authorize' && a !== 'refund') || [1, 2].includes(d.amount) || !changed(pre, post),
  },
  {
    name: 'expired-accepts-no-command',
    pred: (pre, a, d, post) =>
      pre.status !== 'expired' || (a === 'complete' ? post.status === 'expired' : !changed(pre, post)),
  },
  {
    name: 'only-authorized-uncaptured-expires',
    pred: (pre, a, d, post) =>
      post.status !== 'expired' || pre.status === 'expired' || (a === 'expire' && pre.status === 'authorized' && pre.captured === 0),
  },
  {
    name: 'unknown-payment-refuses-commands',
    pred: (pre, a, d, post) => pre.status !== 'none' || a === 'authorize' || !changed(pre, post),
  },
];

export default { stateInvariants, transitionInvariants };

